import { test } from 'node:test';
import assert from 'node:assert/strict';
import { total, itemCount } from '../src/cart.js';

test('total without discount', () => {
  assert.equal(total([{ price: 100, qty: 2 }, { price: 50, qty: 1 }]), 250);
});

const lines = (n, price) => Array.from({ length: n }, () => ({ price, qty: 1 }));

test('customer discount is applied once (issue #12)', () => {
  // 1,000 with a 0.1 discount rate, under 10 lines: 1,000 * 0.9
  assert.equal(total([{ price: 1000, qty: 1 }], 0.1), 900);
});

test('bulk discount is applied once, after the customer discount (issue #12)', () => {
  // 10 lines, subtotal 10,000, 0.1 discount rate: 10,000 * 0.9 = 9,000, then 9,000 * 0.95
  assert.equal(total(lines(10, 1000), 0.1), 8550);
});

test('total with discount rate 0 keeps the bulk-only behaviour', () => {
  // under 10 lines: no discount at all
  assert.equal(total(lines(9, 1000), 0), 9000);
  // 10 lines or more: 5% bulk discount once (10,000 * 0.95)
  assert.equal(total(lines(10, 1000), 0), 9500);
  // rounding to an integer stays as it is (10 * 0.95 = 9.5 -> 10)
  assert.equal(total(lines(10, 1), 0), 10);
});

test('item count', () => {
  assert.equal(itemCount([{ price: 1, qty: 3 }, { price: 1, qty: 2 }]), 5);
});
